#include <stdio.h>

#define MAXN 500005

int X[MAXN];

int main() {
    int n;
    long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &X[i]);
    }

    long long ans = 0;

    if (k == 0) {
        long long zeros = 0;
        for (int i = 0; i < n; i++) {
            if (X[i] == 0) {
                zeros++;
                ans += zeros;
            } else {
                zeros = 0;
            }
        }
    } else {
        int l1 = 0, l2 = 0;
        long long sum1 = 0, sum2 = 0;

        for (int r = 0; r < n; r++) {
            sum1 += X[r];
            while (sum1 > k) {
                sum1 -= X[l1];
                l1++;
            }

            sum2 += X[r];
            while (sum2 >= k) {
                sum2 -= X[l2];
                l2++;
            }

            if (l2 > l1) {
                ans += (l2 - l1);
            }
        }
    }

    printf("%lld\n", ans);

    return 0;
}
